const s=[{id:"bach",name:"Johann Sebastian Bach",lifespan:"1685 – 1750",birthYear:1685,deathYear:1750,category:"MUSIC",subcategory:"Composer",nationality:"German",era:"Baroque",eraColor:"#8B5CF6",bio:"Johann Sebastian Bach stands as one of the supreme architects of Western music. Born into a dynasty of musicians in Eisenach, Germany, he served as organist, choirmaster, and court composer across various German cities before settling as Cantor at the Thomaskirche in Leipzig — a post he held for the last 27 years of his life. Bach synthesized the diverse national styles of his era into an art of extraordinary density and intellectual depth. His output was staggering: over 1,000 surviving works spanning keyboard suites, orchestral concertos, chamber music, organ preludes, and an unmatched corpus of sacred vocal music. The Brandenburg Concertos distilled the Italian concerto into something wholly new; the Well-Tempered Clavier mapped all 24 major and minor keys with poetic rigor; the Mass in B Minor stands as perhaps the greatest choral work in history. Largely neglected after his death, Bach was spectacularly revived by Felix Mendelssohn in 1829, and has never left the center of the repertoire since.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Johann_Sebastian_Bach.jpg/480px-Johann_Sebastian_Bach.jpg",imageCredit:"Elias Gottlob Haussmann, 1748 (public domain)",wikiTitle:"Johann_Sebastian_Bach",keyWorks:[{title:"The Well-Tempered Clavier",year:1722,notes:"Two books of 48 preludes and fugues in every key"},{title:"Brandenburg Concertos",year:1721,notes:"Six concertos for various instruments"},{title:"Mass in B Minor",year:1749,notes:"Monumental sacred choral work"},{title:"Goldberg Variations",year:1741,notes:"Aria with 30 variations for harpsichord"},{title:"St. Matthew Passion",year:1727,notes:"Epic oratorio for double choir"}],quote:"The aim and final end of all music should be none other than the glory of God and the refreshment of the soul.",tags:["baroque","composer","keyboard","sacred","polyphony"]},{id:"beethoven",name:"Ludwig van Beethoven",lifespan:"1770 – 1827",birthYear:1770,deathYear:1827,category:"MUSIC",subcategory:"Composer",nationality:"German",era:"Classical / Romantic",eraColor:"#EC4899",bio:`Ludwig van Beethoven bridged the Classical and Romantic eras with a life story of almost mythic proportion. Born in Bonn, he moved to Vienna in 1792 to study with Haydn and quickly established himself as the greatest pianist of his age. The onset of deafness in his late twenties — a devastating blow for any musician — drove him into isolation and nearly to suicide, but instead unleashed his most revolutionary work. His nine symphonies chart an arc from classical elegance to titanic struggle to transcendent joy. The Ninth Symphony, composed entirely while deaf, culminates in the choral finale setting Schiller's "Ode to Joy" — a declaration of universal brotherhood that remains one of humanity's most powerful artistic statements. Beethoven shattered the formal conventions of his time, expanded the size and emotional scope of every genre he touched, and opened the door to the Romantic era.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Beethoven.jpg/480px-Beethoven.jpg",imageCredit:"Joseph Karl Stieler, 1820 (public domain)",wikiTitle:"Ludwig_van_Beethoven",keyWorks:[{title:"Symphony No. 9 in D minor",year:1824,notes:'Features the famous "Ode to Joy" choral finale'},{title:"Symphony No. 5 in C minor",year:1808,notes:"Opens with the iconic four-note motif"},{title:"Moonlight Sonata",year:1801,notes:"Piano Sonata No. 14 in C# minor"},{title:'Piano Concerto No. 5 "Emperor"',year:1811},{title:"String Quartet No. 14 in C# minor",year:1826,notes:"Late period masterwork in seven movements"}],quote:"Music is a higher revelation than all wisdom and philosophy.",tags:["classical","romantic","symphony","piano","deaf"]},{id:"mozart",name:"Wolfgang Amadeus Mozart",lifespan:"1756 – 1791",birthYear:1756,deathYear:1791,category:"MUSIC",subcategory:"Composer",nationality:"Austrian",era:"Classical",eraColor:"#3B82F6",bio:"Wolfgang Amadeus Mozart remains the most celebrated child prodigy in the history of Western music. Born in Salzburg, he was composing minuets at five and symphonies at eight, touring the courts of Europe with his father Leopold and sister Nannerl. As an adult he settled in Vienna, composing at white heat despite chronic financial difficulty. In a creative life of only thirty-five years he produced over 800 works — 41 symphonies, 27 piano concertos, 23 string quartets, more than 20 operas, and an enormous body of chamber and sacred music — each one characterized by an effortless clarity, singing melodic gift, and perfect formal balance. His operas — Don Giovanni, The Marriage of Figaro, Così fan tutte, The Magic Flute — reinvented the art form and remain cornerstones of the repertoire. He died in Vienna at 35, leaving his Requiem unfinished.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Wolfgang-amadeus-mozart_1.jpg/480px-Wolfgang-amadeus-mozart_1.jpg",imageCredit:"Johann Nepomuk della Croce, c.1780 (public domain)",wikiTitle:"Wolfgang_Amadeus_Mozart",keyWorks:[{title:"Don Giovanni",year:1787,notes:"Opera — considered the supreme operatic masterwork"},{title:'Symphony No. 41 "Jupiter"',year:1788,notes:"His final and grandest symphony"},{title:"Piano Concerto No. 21",year:1785,notes:"The Andante became famous via the 1967 film Elvira Madigan"},{title:"Requiem in D minor",year:1791,notes:"Left unfinished at his death"},{title:"The Magic Flute",year:1791,notes:"Opera — a Masonic fairy tale and his final opera"}],quote:"Neither a lofty degree of intelligence nor imagination nor both together go to the making of genius. Love, love, love, that is the soul of genius.",tags:["classical","prodigy","opera","symphony","vienna"]},{id:"chopin",name:"Frédéric Chopin",lifespan:"1810 – 1849",birthYear:1810,deathYear:1849,category:"MUSIC",subcategory:"Composer & Pianist",nationality:"Polish",era:"Romantic",eraColor:"#F59E0B",bio:"Frédéric Chopin is the supreme poet of the piano. Born near Warsaw to a French father and Polish mother, he showed prodigious talent from childhood and was composing polonaises and mazurkas before his teens. He left Poland for Paris in 1830 — just before the failed Polish uprising — and never returned to his homeland, yet Poland remained the emotional bedrock of his music. In Paris he became the darling of the salons, giving few public concerts but commanding enormous influence through his published compositions. Unlike his virtuoso contemporaries, Chopin wrote almost exclusively for the piano, and in doing so redefined what the instrument could express: the nocturnes achieve a song-like poetry, the études turn technical challenges into profound art, the ballades tell stories of tragic grandeur. His decade-long relationship with the writer George Sand was the great romance of his life. He died of tuberculosis at 39.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Frederic_Chopin_photo.jpeg/480px-Frederic_Chopin_photo.jpeg",imageCredit:"Louis-Auguste Bisson, 1849 (public domain)",wikiTitle:"Frédéric_Chopin",keyWorks:[{title:"Nocturnes (21)",year:1827,notes:"Lyrical pieces that defined nocturnal piano poetry"},{title:"Études Op. 10 & Op. 25",year:1833,notes:"24 études transforming technical exercises into art"},{title:"Ballade No. 1 in G minor",year:1835},{title:'Piano Sonata No. 2 "Funeral March"',year:1839},{title:"Mazurkas (58)",year:1825,notes:"Polish folk dance forms elevated to high art"}],quote:"Bach is an astronomer, discovering the most marvellous stars. Beethoven challenges the universe. I only try to express the soul and the heart of man.",tags:["romantic","piano","polish","nocturne","etude"]},{id:"handel",name:"George Frideric Handel",lifespan:"1685 – 1759",birthYear:1685,deathYear:1759,category:"MUSIC",subcategory:"Composer",nationality:"German-British",era:"Baroque",eraColor:"#8B5CF6",bio:"George Frideric Handel was born in the same year as Bach — 1685 — but followed a radically different path. Born in Halle, Germany, he studied in Italy and ultimately settled in London, becoming the foremost composer in Britain and one of the most celebrated in Europe. Where Bach worked in relative obscurity as a church musician, Handel operated in the glamorous world of opera and public concert life. He wrote over 40 Italian operas for the London stage, and when fashion shifted away from opera seria, he reinvented himself as the master of the English oratorio. Messiah, premiered in Dublin in 1742, has never left the repertoire. The story that King George II rose for the Hallelujah chorus — whether true or legend — captures Handel's extraordinary authority over his audiences. His Water Music and Music for the Royal Fireworks were composed for spectacular outdoor royal occasions on the Thames and in Green Park.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/George_Frideric_Handel_by_Balthasar_Denner.jpg/480px-George_Frideric_Handel_by_Balthasar_Denner.jpg",imageCredit:"Balthasar Denner, c.1726 (public domain)",wikiTitle:"George_Frideric_Handel",keyWorks:[{title:"Messiah",year:1741,notes:"Oratorio — the Hallelujah chorus is world-famous"},{title:"Water Music",year:1717,notes:"Suite of orchestral pieces for a royal Thames excursion"},{title:"Music for the Royal Fireworks",year:1749},{title:"Giulio Cesare",year:1724,notes:"Opera seria — his most revived opera today"}],tags:["baroque","oratorio","opera","british","sacred"]},{id:"vivaldi",name:"Antonio Vivaldi",lifespan:"1678 – 1741",birthYear:1678,deathYear:1741,category:"MUSIC",subcategory:"Composer & Violinist",nationality:"Italian",era:"Baroque",eraColor:"#8B5CF6",bio:`Antonio Vivaldi — "Il Prete Rosso" (the Red Priest) for his flaming red hair — was the dominant Italian composer of the Baroque era and one of the most prolific composers in history. Born in Venice, he was ordained a priest but largely devoted his career to music, spending much of his life at the Ospedale della Pietà, a Venetian orphanage for girls, where he trained one of the finest orchestras in Europe. His output was enormous: over 500 concertos, numerous operas, sacred works, and chamber music. The Four Seasons — four violin concertos each depicting a season through vivid musical imagery — is his most famous work and one of the most recognized compositions in classical music. Bach admired and transcribed several of Vivaldi's concertos, spreading his innovations across Europe. Vivaldi died in Vienna, largely forgotten, only to be dramatically rediscovered in the 20th century.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Vivaldi.jpg/480px-Vivaldi.jpg",imageCredit:"Anon., c.1725 (public domain)",wikiTitle:"Antonio_Vivaldi",keyWorks:[{title:"The Four Seasons",year:1725,notes:"Four violin concertos — Spring, Summer, Autumn, Winter"},{title:"Gloria in D major RV 589",year:1715,notes:"Sacred choral work"},{title:"L'Estro Armonico Op. 3",year:1711,notes:"12 concertos that defined the Baroque concerto form"}],tags:["baroque","violin","italian","concerto","program music"]},{id:"debussy",name:"Claude Debussy",lifespan:"1862 – 1918",birthYear:1862,deathYear:1918,category:"MUSIC",subcategory:"Composer",nationality:"French",era:"Impressionist",eraColor:"#06B6D4",bio:`Claude Debussy transformed Western music at the turn of the 20th century with a style he called "Impressionism" — though he resisted the label. Influenced by Javanese gamelan music at the 1889 Paris Exposition, by Symbolist poetry, and by a deep love of water and light, he developed a radically new harmonic language that dissolved traditional chord progressions in favor of shimmering, ambiguous textures. Prélude à l'après-midi d'un faune (1894) is often cited as the beginning of musical modernism. La Mer depicts the ocean in three orchestral tone paintings of extraordinary sensory immediacy. His two books of piano Préludes remain the pinnacle of French piano literature. Unlike most radicals, Debussy achieved both critical and popular success in his lifetime, though he died during World War I as his health deteriorated from colorectal cancer.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Claude_Debussy_ca_1908%2C_foto_av_F%C3%A9lix_Nadar.jpg/480px-Claude_Debussy_ca_1908%2C_foto_av_F%C3%A9lix_Nadar.jpg",imageCredit:"Félix Nadar, 1908 (public domain)",wikiTitle:"Claude_Debussy",keyWorks:[{title:"Prélude à l'après-midi d'un faune",year:1894,notes:"Orchestral prelude that began musical modernism"},{title:"La Mer",year:1905,notes:"Three symphonic sketches depicting the sea"},{title:"Clair de lune",year:1905,notes:"Third movement of Suite bergamasque — one of the most beloved piano pieces"},{title:"Préludes Books I & II",year:1910,notes:"24 character pieces for piano"},{title:"String Quartet in G minor",year:1893}],quote:"Music is the space between the notes.",tags:["impressionist","french","piano","orchestral","modernism"]},{id:"tchaikovsky",name:"Pyotr Ilyich Tchaikovsky",lifespan:"1840 – 1893",birthYear:1840,deathYear:1893,category:"MUSIC",subcategory:"Composer",nationality:"Russian",era:"Romantic",eraColor:"#F59E0B",bio:'Pyotr Ilyich Tchaikovsky is the most beloved Russian composer and one of the most popular in the entire classical canon. His music possesses an emotional directness and melodic gift that few composers have matched. Born in Votkinsk to a middle-class family, he entered the St. Petersburg Conservatory in his early twenties and spent the rest of his life navigating the tensions between his deeply felt Russianness and his admiration for Western European forms. His three great ballets — Swan Lake, The Sleeping Beauty, and The Nutcracker — transformed ballet music from mere accompaniment into profound art, and are performed worldwide every year. His final three symphonies plumb depths of anguish, triumph, and resignation that feel urgently personal. He died nine days after the premiere of his Sixth Symphony "Pathétique," whose final movement fades to silence like a dying breath.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Tchaikovsky_by_Reutlinger_%28cropped%29.jpg/480px-Tchaikovsky_by_Reutlinger_%28cropped%29.jpg",imageCredit:"Reutlinger Studio, 1888 (public domain)",wikiTitle:"Pyotr_Ilyich_Tchaikovsky",keyWorks:[{title:"Swan Lake",year:1876,notes:"Ballet — one of the most performed ballets in the world"},{title:"The Nutcracker",year:1892,notes:"Ballet — a Christmas tradition worldwide"},{title:'Symphony No. 6 "Pathétique"',year:1893,notes:"His final symphony; premiered 9 days before his death"},{title:"1812 Overture",year:1882,notes:"Commemorates Napoleon's retreat from Moscow; features cannon fire"},{title:"Piano Concerto No. 1 in B♭ minor",year:1875}],tags:["romantic","russian","ballet","symphony","melody"]},{id:"brahms",name:"Johannes Brahms",lifespan:"1833 – 1897",birthYear:1833,deathYear:1897,category:"MUSIC",subcategory:"Composer & Pianist",nationality:"German",era:"Romantic",eraColor:"#F59E0B",bio:`Johannes Brahms carried the weight of Beethoven's legacy more consciously than any of his contemporaries. Born in Hamburg to a modest family, he was championed early by Robert and Clara Schumann — a relationship that defined his emotional life. He spent decades wrestling with the symphony form before completing his First at 43. Critics hailed it as "Beethoven's Tenth." He ultimately wrote four symphonies, each a masterwork of structural rigor and emotional depth. Unlike Wagner, who threw out traditional forms in favor of the Music Drama, Brahms deepened and enriched classical structure — earning him the title of the "conservative" in the bitter Wagner-Brahms aesthetic wars. His chamber music is incomparable in richness: his string sextets, piano quartets, and clarinet quintet are among the finest works in the genre. The German Requiem, setting texts from Luther's Bible, is among the most consoling works in the choral literature.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Brahms-1889.jpg/480px-Brahms-1889.jpg",imageCredit:"Maria Fellinger, 1889 (public domain)",wikiTitle:"Johannes_Brahms",keyWorks:[{title:"Symphony No. 1 in C minor",year:1876,notes:`Called "Beethoven's Tenth" by critics`},{title:"A German Requiem",year:1869,notes:"Choral masterpiece setting texts from Luther's Bible"},{title:"Violin Concerto in D major",year:1878},{title:"Intermezzo in A major Op. 118 No. 2",year:1893,notes:"Late piano miniature of great tenderness"}],tags:["romantic","german","symphony","chamber","classical tradition"]},{id:"wagner",name:"Richard Wagner",lifespan:"1813 – 1883",birthYear:1813,deathYear:1883,category:"MUSIC",subcategory:"Composer",nationality:"German",era:"Romantic",eraColor:"#F59E0B",bio:'Richard Wagner is the most consequential and controversial figure in the history of opera. He did not simply write operas — he invented a new art form: the Gesamtkunstwerk (total artwork), in which music, drama, poetry, visual spectacle, and staging fuse into a seamless whole. His mature works — collectively called music dramas — eliminated the aria-and-recitative structure of traditional opera in favor of an unbroken musical flow organized around leitmotifs: recurring musical themes tied to characters, objects, and ideas. The Ring Cycle — Der Ring des Nibelungen — is perhaps the most ambitious artistic project ever completed: four operas totaling fifteen hours of music, retelling Norse mythology on a cosmic scale. Wagner built his own theater at Bayreuth specifically to perform these works. His harmonic innovations, particularly the "Tristan chord" of Tristan und Isolde, dissolved traditional tonality and opened the door to modernism.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Richard_Wagner_-_Portrait_by_Caesar_Willich_from_1862_cropped.jpg/480px-Richard_Wagner_-_Portrait_by_Caesar_Willich_from_1862_cropped.jpg",imageCredit:"Caesar Willich, 1862 (public domain)",wikiTitle:"Richard_Wagner",keyWorks:[{title:"Der Ring des Nibelungen",year:1876,notes:"Four-opera cycle: Das Rheingold, Die Walküre, Siegfried, Götterdämmerung"},{title:"Tristan und Isolde",year:1865,notes:"Opened the path to musical modernism with radical harmony"},{title:"Die Meistersinger von Nürnberg",year:1868,notes:"His only comedy — warmly human and profound"},{title:"Parsifal",year:1882,notes:"His final opera — a sacred festival play"}],tags:["romantic","opera","german","leitmotif","gesamtkunstwerk"]},{id:"verdi",name:"Giuseppe Verdi",lifespan:"1813 – 1901",birthYear:1813,deathYear:1901,category:"MUSIC",subcategory:"Composer",nationality:"Italian",era:"Romantic",eraColor:"#F59E0B",bio:`Giuseppe Verdi dominated Italian opera for fifty years with a series of works that combined theatrical power, melodic invention, and deep humanity. Born in Le Roncole, in the Duchy of Parma, he rose from humble origins to become Italy's most beloved composer and a symbol of the Risorgimento — the movement for Italian national unification. His early operas, notably Nabucco (whose chorus "Va, pensiero" became a surrogate national anthem), established his reputation. His middle period — Rigoletto, Il trovatore, La traviata — produced three of the most performed operas in the world. In his seventies, after a long retirement, he returned with two Shakespearean masterpieces: Otello and Falstaff, arguably the greatest serious and comic operas ever written. Unlike Wagner, who theorized endlessly about what opera should be, Verdi simply wrote music of overwhelming theatrical truth.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Giuseppe_Verdi_by_Giovanni_Boldini%2C_1886.jpg/480px-Giuseppe_Verdi_by_Giovanni_Boldini%2C_1886.jpg",imageCredit:"Giovanni Boldini, 1886 (public domain)",wikiTitle:"Giuseppe_Verdi",keyWorks:[{title:"Rigoletto",year:1851,notes:'Opera — "La donna è mobile" is one of the most famous arias'},{title:"La traviata",year:1853},{title:"Aida",year:1871,notes:"Grand opera commissioned for the Cairo Opera House"},{title:"Otello",year:1887,notes:"Shakespearean opera, his penultimate work"},{title:"Falstaff",year:1893,notes:"Comic opera, his final work at age 79"}],tags:["romantic","opera","italian","shakespeare","risorgimento"]},{id:"stravinsky",name:"Igor Stravinsky",lifespan:"1882 – 1971",birthYear:1882,deathYear:1971,category:"MUSIC",subcategory:"Composer",nationality:"Russian",era:"Modern",eraColor:"#10B981",bio:`Igor Stravinsky is the most versatile and influential composer of the 20th century. Born near St. Petersburg, he studied with Rimsky-Korsakov and burst onto the world stage with three revolutionary ballet scores for Sergei Diaghilev's Ballets Russes. The Rite of Spring, premiering in Paris in 1913, provoked a near-riot in the audience with its savage rhythmic irregularity, dissonant harmonic clusters, and sacrificial subject matter — but it permanently transformed Western music. After World War I, Stravinsky invented a cool, ironic "neoclassical" style inspired by Bach and Mozart, before adopting twelve-tone serialism in his final decades. This chameleonic reinvention across nearly seventy years of composition is without parallel. He spent much of his adult life as an émigré — in Switzerland, France, and finally the United States — and died in Venice, returning to the city that had shaped his early career.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Igor_Stravinsky_LOC_32304_cropped.jpg/480px-Igor_Stravinsky_LOC_32304_cropped.jpg",imageCredit:"Library of Congress, c.1915 (public domain)",wikiTitle:"Igor_Stravinsky",keyWorks:[{title:"The Rite of Spring",year:1913,notes:"Ballet — its premiere provoked a riot; transformed modern music"},{title:"The Firebird",year:1910,notes:"His first ballet for Diaghilev's Ballets Russes"},{title:"Petrushka",year:1911},{title:"Symphony of Psalms",year:1930,notes:"Neoclassical choral-orchestral masterpiece"}],tags:["modern","russian","ballet","neoclassicism","serialism"]},{id:"scott-joplin",name:"Scott Joplin",lifespan:"1868 – 1917",birthYear:1868,deathYear:1917,category:"MUSIC",subcategory:"Composer & Pianist",nationality:"American",era:"Ragtime Era",eraColor:"#F97316",bio:'Scott Joplin was the "King of Ragtime" — the composer who elevated a dance hall genre to the status of serious art. Born in Texarkana, Texas, the son of a formerly enslaved man and a freeborn woman, Joplin showed early musical talent and studied formal theory while playing in bars and brothels across the Mississippi delta. His Maple Leaf Rag (1899) was the first piece of sheet music to sell one million copies. His two-act ragtime opera Treemonisha (1911), written with his own libretto, was a visionary attempt to create a Black American operatic tradition. He died in a Manhattan institution in 1917, unable to see Treemonisha produced in his lifetime. Joplin was rediscovered in the 1970s when his music was used in the Oscar-winning film The Sting, and in 1976 he was posthumously awarded a special Pulitzer Prize — the first African American composer to receive one.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Scott_Joplin_-_Project_Gutenberg_eText_20096.jpg/480px-Scott_Joplin_-_Project_Gutenberg_eText_20096.jpg",imageCredit:"S. Simon & Co., 1903 (public domain)",wikiTitle:"Scott_Joplin",keyWorks:[{title:"Maple Leaf Rag",year:1899,notes:"First sheet music to sell 1 million copies"},{title:"The Entertainer",year:1902,notes:"Became internationally famous from the 1973 film The Sting"},{title:"Treemonisha",year:1911,notes:"Ragtime opera — a landmark in African American music history"}],tags:["ragtime","american","piano","african-american","opera"]},{id:"louis-armstrong",name:"Louis Armstrong",lifespan:"1901 – 1971",birthYear:1901,deathYear:1971,category:"MUSIC",subcategory:"Trumpeter & Vocalist",nationality:"American",era:"Jazz Age",eraColor:"#F59E0B",bio:`Louis Armstrong — "Satchmo" — is the defining figure of jazz: the man who gave the music its voice, its swagger, and its global reach. Born in the Storyville district of New Orleans in 1901, he grew up in poverty and spent time as a youth in the Colored Waif's Home, where he first learned the cornet. Mentored by Joe "King" Oliver, he moved to Chicago in 1922 and began recording the Hot Five and Hot Seven sessions (1925–1928) — a series of recordings so technically brilliant and emotionally rich that they redefined what jazz improvisation could be. His warm, gravelly voice became as beloved as his trumpet. By the 1930s he was a global superstar, and his recording of "What a Wonderful World" (1967) remains one of the most recognizable songs in history. Armstrong was a cultural ambassador for America in the Cold War and a profoundly influential figure for every musician who followed.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Louis_Armstrong_restored.jpg/480px-Louis_Armstrong_restored.jpg",imageCredit:"William P. Gottlieb, 1947 (public domain)",wikiTitle:"Louis_Armstrong",keyWorks:[{title:"West End Blues",year:1928,notes:"Hot Five recording — his trumpet introduction is one of jazz's defining moments"},{title:"What a Wonderful World",year:1967,notes:"One of the most beloved songs ever recorded"},{title:"Heebie Jeebies",year:1926,notes:"Early scat singing recording"},{title:"Hello, Dolly!",year:1964,notes:"Went to No. 1, ending the Beatles' record streak"}],quote:"If you have to ask what jazz is, you'll never know.",tags:["jazz","new-orleans","trumpet","improvisation","american"]},{id:"duke-ellington",name:"Duke Ellington",lifespan:"1899 – 1974",birthYear:1899,deathYear:1974,category:"MUSIC",subcategory:"Composer, Bandleader & Pianist",nationality:"American",era:"Jazz Age / Swing Era",eraColor:"#F59E0B",bio:`Edward Kennedy "Duke" Ellington was the greatest composer in the history of jazz and one of the most important American composers of any genre. Born in Washington D.C. to a middle-class Black family, he moved to New York and by 1927 was leading the house band at the Cotton Club in Harlem — the most prestigious jazz venue in America. Ellington composed over 3,000 pieces and uniquely wrote to showcase the individual voices of his band members, treating the orchestra itself as his instrument. His extended works — Black, Brown and Beige (premiered at Carnegie Hall in 1943), the Sacred Concerts of his later years — pushed jazz into concert hall territory without losing its soul. He collaborated with Billy Strayhorn for three decades in one of music's great creative partnerships. Ellington was nominated for a Pulitzer Prize in 1965; it was not awarded. He received the Presidential Medal of Freedom in 1969.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Duke_Ellington_-_publicity.jpg/480px-Duke_Ellington_-_publicity.jpg",imageCredit:"RKO Radio Pictures, 1943 (public domain)",wikiTitle:"Duke_Ellington",keyWorks:[{title:"Mood Indigo",year:1930},{title:"Take the A Train",year:1941,notes:"Written by Billy Strayhorn — became the band's signature tune"},{title:"Black, Brown and Beige",year:1943,notes:"Extended orchestral work premiering at Carnegie Hall"},{title:"It Don't Mean a Thing (If It Ain't Got That Swing)",year:1931}],quote:"There are two kinds of music. Good music, and the other kind.",tags:["jazz","swing","composition","big-band","american"]},{id:"billie-holiday",name:"Billie Holiday",lifespan:"1915 – 1959",birthYear:1915,deathYear:1959,category:"MUSIC",subcategory:"Vocalist",nationality:"American",era:"Jazz Age / Swing Era",eraColor:"#F59E0B",bio:`Billie Holiday possessed the most emotionally expressive voice in jazz — arguably in American music. Born Eleanora Fagan in Philadelphia, she grew up in poverty in Baltimore, survived abuse and hardship, and arrived in New York as a teenager. She began recording in 1933 with Benny Goodman and soon developed a style unlike anything before it: her voice caressed and bent notes behind the beat, investing even the lightest material with the weight of lived experience. Her collaboration with Lester Young — who gave her the nickname "Lady Day" — produced some of jazz's most intimate recordings. "Strange Fruit" (1939), a devastating protest song about lynching in the American South, was a landmark in political music and arguably the first protest song of the modern era. She struggled throughout her life with heroin addiction, racism, and FBI harassment (J. Edgar Hoover saw "Strange Fruit" as a political threat), and died at 44, still under police guard in her hospital room.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Billie_Holiday.jpg/480px-Billie_Holiday.jpg",imageCredit:"William P. Gottlieb, 1947 (public domain)",wikiTitle:"Billie_Holiday",keyWorks:[{title:"Strange Fruit",year:1939,notes:"Protest song about lynching — one of the most important recordings in American history"},{title:"God Bless the Child",year:1941,notes:"Written by Holiday herself — one of her few original compositions"},{title:"Lady in Satin",year:1958,notes:"Her final album, recorded when her voice showed the ravages of her life"}],quote:"I can't stand to sing the same song the same way two nights in succession. If you can, then it ain't music, it's close-order drill.",tags:["jazz","blues","vocalist","protest","american"]},{id:"ella-fitzgerald",name:"Ella Fitzgerald",lifespan:"1917 – 1996",birthYear:1917,deathYear:1996,category:"MUSIC",subcategory:"Vocalist",nationality:"American",era:"Swing / Bebop Era",eraColor:"#F59E0B",bio:`Ella Fitzgerald — "The First Lady of Song" — possessed a voice of staggering technical perfection combined with an infectious warmth and joy that made her the most admired vocalist in jazz history. Born in Newport News, Virginia, she was discovered at 17 at the Apollo Theater's Amateur Night and quickly became the featured vocalist with Chick Webb's Orchestra. After Webb's death she led the band herself before embarking on a solo career under the management of Norman Granz. Her landmark "Songbook" series — recording the complete catalogues of Cole Porter, Rodgers & Hart, Duke Ellington, George and Ira Gershwin, and others — did more than any other project to establish the "American Songbook" as a canonical repertoire. Her scat singing was matchless: a pure, joyful exploration of the voice as instrument. She won 13 Grammy Awards and the Presidential Medal of Freedom.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Ella_Fitzgerald_in_1968.jpg/480px-Ella_Fitzgerald_in_1968.jpg",imageCredit:"CBS Television, 1968 (public domain)",wikiTitle:"Ella_Fitzgerald",keyWorks:[{title:"A-Tisket, A-Tasket",year:1938,notes:"Her first major hit, recorded with Chick Webb"},{title:"The Cole Porter Songbook",year:1956,notes:'First of the landmark "Songbook" series'},{title:"How High the Moon",year:1947,notes:"Showcases her extraordinary scat singing"}],quote:"The only thing better than singing is more singing.",tags:["jazz","vocals","scat","american-songbook","swing"]},{id:"miles-davis",name:"Miles Davis",lifespan:"1926 – 1991",birthYear:1926,deathYear:1991,category:"MUSIC",subcategory:"Trumpeter & Bandleader",nationality:"American",era:"Bebop / Cool Jazz / Fusion",eraColor:"#3B82F6",bio:'Miles Davis reinvented jazz more times than any other musician in its history. Born to a prosperous Black family in Alton, Illinois, he moved to New York at 18 ostensibly to study at Juilliard but really to play with Charlie Parker. His 1949–50 "Birth of the Cool" sessions introduced a new, restrained, chamber-influenced sound that spawned the Cool Jazz movement. In 1955 his classic quintet — with John Coltrane, Red Garland, Paul Chambers, and Philly Joe Jones — revolutionized the small group format. Kind of Blue (1959) remains the best-selling jazz album ever recorded, introducing modal jazz to the world with a casual grace that disguised its radicalism. In 1970 he shocked the jazz world again with Bitches Brew, merging jazz with rock and funk amplification to create fusion. Through five decades and multiple stylistic incarnations, Davis remained perpetually restless and forward-looking.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Miles_Davis_-_1984.jpg/480px-Miles_Davis_-_1984.jpg",imageCredit:"Felix Wirth (CC BY 4.0)",wikiTitle:"Miles_Davis",keyWorks:[{title:"Kind of Blue",year:1959,notes:"The best-selling jazz album ever; defined modal jazz"},{title:"Birth of the Cool",year:1957,notes:"Sessions recorded 1949–50; launched Cool Jazz"},{title:"Sketches of Spain",year:1960,notes:"Collaboration with arranger Gil Evans"},{title:"Bitches Brew",year:1970,notes:"Electric fusion masterpiece that shocked the jazz world"}],quote:"Don't play what's there, play what's not there.",tags:["jazz","bebop","cool-jazz","fusion","trumpet"]},{id:"bessie-smith",name:"Bessie Smith",lifespan:"1894 – 1937",birthYear:1894,deathYear:1937,category:"MUSIC",subcategory:"Vocalist",nationality:"American",era:"Blues",eraColor:"#6366F1",bio:`Bessie Smith was the "Empress of the Blues" — the most commercially successful Black recording artist of the 1920s and the dominant figure in classic blues. Born in Chattanooga, Tennessee, she was orphaned early and began performing with the Moses Stokes tent show alongside Ma Rainey, who became her mentor. By the 1920s she was recording for Columbia Records and selling 100,000 copies of each release — extraordinary numbers for any artist at the time. Her voice was a force of nature: powerful, emotionally devastating, capable of intimacy and grandeur in the same breath. Songs like "Downhearted Blues," "Backwater Blues," and "Nobody Knows You When You're Down and Out" spoke directly to the Great Migration experience of Black Americans moving from the rural South to the urban North. She died at 43 in a car accident in Mississippi. Janis Joplin, who idolized her, paid for her tombstone in 1970.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Bessie_Smith_1936.jpg/480px-Bessie_Smith_1936.jpg",imageCredit:"Carl Van Vechten, 1936 (public domain)",wikiTitle:"Bessie_Smith",keyWorks:[{title:"Downhearted Blues",year:1923,notes:"Her debut record — sold 750,000 copies"},{title:"Backwater Blues",year:1927,notes:"About the Great Mississippi Flood of 1927"},{title:"Nobody Knows You When You're Down and Out",year:1929}],tags:["blues","jazz","african-american","vocalist","1920s"]},{id:"ma-rainey",name:"Ma Rainey",lifespan:"1886 – 1939",birthYear:1886,deathYear:1939,category:"MUSIC",subcategory:"Vocalist",nationality:"American",era:"Blues",eraColor:"#6366F1",bio:'Gertrude "Ma" Rainey was the "Mother of the Blues" — the first great professional blues singer and the direct link between rural Southern folk music and the recorded blues tradition. Born in Columbus, Georgia, she began performing in tent shows and minstrel troupes in her teens and by the 1910s was touring the South with her own company, "Madam Gertrude Ma Rainey and Her Georgia Smart Sets." She was already a seasoned professional with a vast repertoire when she finally began recording for Paramount Records in 1923, at age 37. Her recordings — made in Chicago over five years — capture a raw, earthy power that studio technology of the era could barely contain. She mentored Bessie Smith in her early career and was openly bisexual at a time when this required extraordinary courage. She retired to Columbus in 1935 and ran two theaters until her death.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Ma_Rainey.jpg/480px-Ma_Rainey.jpg",imageCredit:"Paramount Records, 1923 (public domain)",wikiTitle:"Ma_Rainey",keyWorks:[{title:"C.C. Rider",year:1924},{title:"Prove It on Me Blues",year:1928,notes:"One of the earliest LGBTQ+ themed songs in recorded music"},{title:"Bo Weevil Blues",year:1923,notes:"One of her earliest and most influential recordings"}],tags:["blues","african-american","vocalist","lgbtq","1920s"]}],l=[{id:"charlie-chaplin",name:"Charlie Chaplin",lifespan:"1889 – 1977",birthYear:1889,deathYear:1977,category:"FILM_TV",subcategory:"Actor, Director & Composer",nationality:"British",era:"Silent Film / Golden Age",eraColor:"#8B5CF6",bio:'Charlie Chaplin is the most universally beloved figure in cinema history. Born in South London to music-hall performers, he endured a childhood of poverty and hardship that would later fuel his art. He came to Hollywood with the Karno comedy troupe in 1913 and by 1915 had created the "Little Tramp" — the bowler-hatted, cane-twirling vagabond who became the most recognized figure in the world. Chaplin did not merely star in his films but wrote, directed, produced, and eventually scored them — a degree of creative control unprecedented in Hollywood. His great silent features — The Kid, The Gold Rush, City Lights, Modern Times — balance slapstick comedy with genuine pathos in a way that has never been surpassed. The Great Dictator (1940), his first sound film, was a direct satire of Hitler and Mussolini and contains a closing speech of stirring moral beauty. Driven from America by McCarthyism in 1952, he spent his last decades in Switzerland.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Charlie_Chaplin.jpg/480px-Charlie_Chaplin.jpg",imageCredit:"Anon., c.1920 (public domain)",wikiTitle:"Charlie_Chaplin",keyWorks:[{title:"The Gold Rush",year:1925,notes:"His personal favorite of his own films"},{title:"City Lights",year:1931,notes:"Silent film with synchronised score — the flower-girl sequence is one of cinema's greatest endings"},{title:"Modern Times",year:1936,notes:"Satire of industrialization — his last silent-era film"},{title:"The Great Dictator",year:1940,notes:"His first sound film — a direct satire of Hitler"},{title:"Limelight",year:1952,notes:"His most autobiographical work"}],quote:"A day without laughter is a day wasted.",tags:["silent film","comedy","director","actor","chaplin"]},{id:"alfred-hitchcock",name:"Alfred Hitchcock",lifespan:"1899 – 1980",birthYear:1899,deathYear:1980,category:"FILM_TV",subcategory:"Director",nationality:"British",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:'Alfred Hitchcock is the undisputed "Master of Suspense" — the director who most completely understood how cinema creates and manipulates emotion in an audience. Born in Leytonstone, London, he began his career as a title card designer in the silent era and directed his first notable film in 1925. His British period produced a series of accomplished thrillers; his move to Hollywood in 1939 produced his greatest work. Hitchcock was the supreme technician of cinema: he pre-visualized every shot in elaborate storyboards before filming began, understanding instinctively how editing, camera movement, and musical score combine to generate suspense, dread, or shock. Vertigo — long dismissed and now ranked the greatest film ever made — is a study in obsession, illusion, and the cruelty of desire. Psycho shattered the conventions of the studio system. The Birds operates without explanation, creating existential dread from the everyday. Despite his popular mastery, the Academy never gave him a Directing Oscar.',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Alfred_Hitchcock.png/480px-Alfred_Hitchcock.png",imageCredit:"CBS Television, 1955 (public domain)",wikiTitle:"Alfred_Hitchcock",keyWorks:[{title:"Vertigo",year:1958,notes:"Ranked by Sight & Sound as the greatest film ever made (2012)"},{title:"Rear Window",year:1954,notes:"A perfect Hitchcock trap: the voyeur as audience surrogate"},{title:"Psycho",year:1960,notes:"Shattered Hollywood conventions; invented the slasher genre"},{title:"North by Northwest",year:1959,notes:"The quintessential wrong-man thriller"},{title:"The Birds",year:1963}],quote:"Give them pleasure — the same pleasure they have when they wake up from a nightmare.",tags:["suspense","thriller","director","british","classic-hollywood"]},{id:"orson-welles",name:"Orson Welles",lifespan:"1915 – 1985",birthYear:1915,deathYear:1985,category:"FILM_TV",subcategory:"Director, Actor & Writer",nationality:"American",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:"Orson Welles arrived in Hollywood at 25 having never directed a film and made Citizen Kane — widely considered the greatest American film ever made. Born in Kenosha, Wisconsin to an inventor father and pianist mother, he was a child prodigy in theater and radio. His 1938 radio adaptation of War of the Worlds reportedly caused widespread panic among listeners who believed a Martian invasion was actually occurring. Citizen Kane (1941), made with total creative freedom after RKO bet on the theatrical wunderkind, introduced a suite of cinematic innovations — deep focus photography, non-linear structure, extreme low angles, overlapping dialogue — that revolutionized filmmaking. Hollywood, intimidated and threatened by his genius, sabotaged his subsequent projects relentlessly. He spent most of the rest of his career in Europe, acting in films for money to finance his own projects. Touch of Evil (1958), his noir masterpiece, opens with one of cinema's most celebrated long takes.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Orson_Welles_as_Kane.jpg/480px-Orson_Welles_as_Kane.jpg",imageCredit:"RKO Pictures, 1941 (public domain)",wikiTitle:"Orson_Welles",keyWorks:[{title:"Citizen Kane",year:1941,notes:"Ranked the greatest film ever made for decades — also his debut feature"},{title:"The Magnificent Ambersons",year:1942,notes:"Masterpiece truncated by the studio"},{title:"Touch of Evil",year:1958,notes:"Opens with a legendary 3-minute uncut tracking shot"},{title:"F for Fake",year:1973,notes:"Essay film on art, forgery, and truth"}],quote:"I began at the top and have been working my way down ever since.",tags:["director","actor","american","film-noir","cinema-history"]},{id:"buster-keaton",name:"Buster Keaton",lifespan:"1895 – 1966",birthYear:1895,deathYear:1966,category:"FILM_TV",subcategory:"Actor & Director",nationality:"American",era:"Silent Film",eraColor:"#8B5CF6",bio:`Buster Keaton — "The Great Stone Face" — was the supreme poet of silent film comedy. Where Chaplin played to the emotions, Keaton played to geometry and physics: his comedy was architectural, choreographic, a man in perfect collision with an indifferent universe, maintaining the same deadpan expression whatever catastrophe befell him. Born into a vaudeville family — his parents' act used him as a human prop from infancy — he learned to fall and take physical punishment without flinching. His great silent features — The General, Sherlock Jr., The Navigator, Seven Chances — are marvels of physical comedy that simultaneously work as genuine dramatic films. The General (1926) is perhaps the most technically demanding film of the silent era: Keaton himself drove the locomotive, organized the stunts, and directed the entire Civil War chase sequence. Talking pictures ended his golden era, but critical reassessment has placed him alongside Chaplin as the co-equal giant of silent comedy.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Buster_Keaton_General_2.jpg/480px-Buster_Keaton_General_2.jpg",imageCredit:"United Artists, 1926 (public domain)",wikiTitle:"Buster_Keaton",keyWorks:[{title:"The General",year:1926,notes:"Civil War chase comedy — his masterpiece; a critical and commercial failure on release"},{title:"Sherlock Jr.",year:1924,notes:"A film projectionist dreams himself into the movie — meta-cinema before the term existed"},{title:"The Navigator",year:1924},{title:"Steamboat Bill, Jr.",year:1928,notes:"Contains the famous house-front falling-on-Keaton gag"}],tags:["silent film","comedy","stunt","director","american"]},{id:"fritz-lang",name:"Fritz Lang",lifespan:"1890 – 1976",birthYear:1890,deathYear:1976,category:"FILM_TV",subcategory:"Director",nationality:"German-American",era:"German Expressionism / Film Noir",eraColor:"#374151",bio:"Fritz Lang is the visionary director of German Expressionist cinema and one of the founding fathers of film noir. Born in Vienna, he worked in Berlin's thriving Weimar-era film industry, producing a series of technically astounding films. Metropolis (1927) — a dystopian science-fiction epic set in a divided future city — remains one of the most influential films ever made; every science-fiction film owes it a debt. M (1931), his first sound film, starred Peter Lorre as a child murderer and pioneered the psychological thriller, using sound in ways that still feel modern. When the Nazis came to power in 1933, Lang — whose mother was Jewish — fled Germany despite an offer from Goebbels to head the German film industry. He reinvented himself in Hollywood, directing a series of hard-edged noir thrillers including The Big Heat and While the City Sleeps. His influence on cinema is incalculable.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Fritz_Lang.jpg/480px-Fritz_Lang.jpg",imageCredit:"Anon., c.1930 (public domain)",wikiTitle:"Fritz_Lang",keyWorks:[{title:"Metropolis",year:1927,notes:"Landmark sci-fi epic — influenced virtually every dystopian film ever made"},{title:"M",year:1931,notes:"Psychological thriller pioneering the use of sound as dramatic tool"},{title:"The Big Heat",year:1953,notes:"Dark Hollywood noir"},{title:"The Nibelungen",year:1924,notes:"Two-part epic retelling the German mythological cycle"}],tags:["expressionism","film-noir","sci-fi","german","silent-film"]},{id:"sergei-eisenstein",name:"Sergei Eisenstein",lifespan:"1898 – 1948",birthYear:1898,deathYear:1948,category:"FILM_TV",subcategory:"Director & Film Theorist",nationality:"Russian",era:"Soviet Montage",eraColor:"#EF4444",bio:`Sergei Eisenstein invented montage theory — the intellectual and emotional power generated by the collision of two separate shots — and in doing so gave cinema its most fundamental theoretical framework. Born in Riga to a Jewish family, he abandoned engineering to work in theater before turning to film. Battleship Potemkin (1925) — made for the 20th anniversary of the 1905 Revolution — is the most analyzed film in cinema history; its Odessa Steps sequence, in which Czarist troops massacre civilians on a monumental staircase, is cited by virtually every subsequent filmmaker as a key influence. October (1928), his reconstruction of the Bolshevik seizure of power, further developed his theory of "intellectual montage" — using film images as ideograms that combine to create abstract concepts. His sound-era masterpiece Alexander Nevsky (1938), with its magnificent Prokofiev score, stands as one of cinema's greatest collaborations.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Sergei_Eisenstein_1945.jpg/480px-Sergei_Eisenstein_1945.jpg",imageCredit:"Anon., 1945 (public domain)",wikiTitle:"Sergei_Eisenstein",keyWorks:[{title:"Battleship Potemkin",year:1925,notes:"The Odessa Steps sequence is cinema's most analyzed scene"},{title:"Strike",year:1925,notes:"His debut feature — montage theory in embryo"},{title:"October (Ten Days That Shook the World)",year:1928},{title:"Alexander Nevsky",year:1938,notes:"With Prokofiev's score — a landmark film-music collaboration"},{title:"Ivan the Terrible",year:1944}],tags:["soviet","montage","silent-film","theory","director"]},{id:"akira-kurosawa",name:"Akira Kurosawa",lifespan:"1910 – 1998",birthYear:1910,deathYear:1998,category:"FILM_TV",subcategory:"Director",nationality:"Japanese",era:"Post-War Japanese Cinema",eraColor:"#10B981",bio:"Akira Kurosawa is the most internationally celebrated Japanese filmmaker and one of the most influential directors in cinema history. Born in Tokyo, he trained as a painter before entering film as an assistant director. Rashomon (1950) — which tells the same story from four irreconcilable perspectives — won the Golden Lion at Venice and introduced Japanese cinema to the Western world, transforming the international film landscape. Seven Samurai (1954), widely considered the greatest action film ever made, created the template for the team-of-heroes narrative that has been remade and reworked hundreds of times, most famously as The Magnificent Seven. His films combine Japanese aesthetic sensibility — the influence of Noh theater, calligraphy, and samurai tradition — with the Western narrative drive of John Ford and the social consciousness of Dostoevsky. The last decade of his career produced Kagemusha and Ran — two of cinema's most visually ravishing epics.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Akira_Kurosawa.jpg/480px-Akira_Kurosawa.jpg",imageCredit:"Anon., 1962 (public domain)",wikiTitle:"Akira_Kurosawa",keyWorks:[{title:"Seven Samurai",year:1954,notes:"The greatest action film ever made; template for countless team-heist films"},{title:"Rashomon",year:1950,notes:"Four accounts of the same crime — introduced Japanese cinema to the world"},{title:"Ikiru",year:1952,notes:"A dying bureaucrat finds meaning — among cinema's most moving films"},{title:"Ran",year:1985,notes:"King Lear set in feudal Japan — a visual epic on a massive scale"},{title:"Yojimbo",year:1961,notes:"Inspired A Fistful of Dollars and the entire Spaghetti Western genre"}],tags:["japanese","samurai","director","akira","post-war"]},{id:"billy-wilder",name:"Billy Wilder",lifespan:"1906 – 2002",birthYear:1906,deathYear:2002,category:"FILM_TV",subcategory:"Director & Screenwriter",nationality:"American",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:"Billy Wilder was the greatest screenwriter-director in Hollywood history and the man who most brilliantly navigated the tension between mass entertainment and serious adult art. Born Samuel Wilder in the Austro-Hungarian empire, he worked as a journalist and screenwriter in Berlin before fleeing the Nazis in 1933 and eventually landing in Hollywood. Working first as a screenwriter with Charles Brackett, he graduated to directing and produced a series of masterworks across multiple genres. Double Indemnity (1944) with its femme fatale and doomed lovers is the archetypal film noir. Sunset Boulevard (1950) is the most savage examination of Hollywood's mythology. Some Like It Hot (1959) — arguably the greatest comedy in American cinema — played drag farce against a backdrop of mob violence and contains Marilyn Monroe's finest screen performance. The Apartment (1960) won five Academy Awards. Wilder maintained his cynicism and his humanity in perfect balance throughout.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Billy_Wilder_Sabrina_1954.jpg/480px-Billy_Wilder_Sabrina_1954.jpg",imageCredit:"Paramount Pictures, 1954 (public domain)",wikiTitle:"Billy_Wilder",keyWorks:[{title:"Some Like It Hot",year:1959,notes:"Regularly ranked the greatest comedy in American cinema"},{title:"Sunset Boulevard",year:1950,notes:"The most devastating dissection of Hollywood mythology"},{title:"Double Indemnity",year:1944,notes:"Archetypal film noir"},{title:"The Apartment",year:1960,notes:"Won Best Picture, Director, and Screenplay at the Academy Awards"},{title:"Stalag 17",year:1953}],quote:"If you're going to tell people the truth, be funny or they'll kill you.",tags:["comedy","film-noir","director","screenwriter","golden-age"]},{id:"katharine-hepburn",name:"Katharine Hepburn",lifespan:"1907 – 2003",birthYear:1907,deathYear:2003,category:"FILM_TV",subcategory:"Actress",nationality:"American",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:'Katharine Hepburn holds a record that will likely never be broken: four Academy Awards for Best Actress, spread across an extraordinary career spanning six decades. Born in Hartford, Connecticut to progressive, upper-class parents — her father a physician, her mother a prominent suffragette — she brought an unconventional intelligence and independence to every role she played. Labeled "box office poison" by theater owners in 1938, she bought out her RKO contract, returned to Broadway in The Philadelphia Story, and bought the film rights — coming back to Hollywood on her own terms. Her nine-film collaboration with Spencer Tracy — whom she loved for 26 years while he remained legally married to his wife — produced some of the wittiest and most deeply felt comedies in cinema. In her later career she commanded the screen with an authority few actors of any era have matched: The Lion in Winter (1968), On Golden Pond (1981).',imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Katharine_Hepburn_1936.jpg/480px-Katharine_Hepburn_1936.jpg",imageCredit:"RKO Radio Pictures, 1936 (public domain)",wikiTitle:"Katharine_Hepburn",keyWorks:[{title:"Morning Glory",year:1933,notes:"Her first Academy Award"},{title:"The Philadelphia Story",year:1940,notes:'Her return to Hollywood after being labeled "box office poison"'},{title:"The African Queen",year:1951,notes:"With Humphrey Bogart"},{title:"The Lion in Winter",year:1968,notes:"Her third Academy Award"}],tags:["actress","golden-age","american","independent","four-oscars"]},{id:"humphrey-bogart",name:"Humphrey Bogart",lifespan:"1899 – 1957",birthYear:1899,deathYear:1957,category:"FILM_TV",subcategory:"Actor",nationality:"American",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:"Humphrey Bogart is the most iconic male screen presence in the history of Hollywood: the world-weary cynical detective, the tough-talking idealist who cares underneath the hardboiled exterior. Born in Manhattan to a physician father and portrait artist mother, he worked on Broadway before Hollywood. It was his role as gangster Duke Mantee in the Broadway and film versions of The Petrified Forest (1936) that made his name. The Maltese Falcon (1941) established him as the quintessential private eye; Casablanca (1942) made him a global romantic icon. He worked with virtually every major director of the era — John Huston, Howard Hawks, Michael Curtiz — and in 1948 won his only Academy Award for The African Queen. His relationship with Lauren Bacall, whom he met when she was 19 and he was 44, was one of Hollywood's great love stories. He died of esophageal cancer at 57.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Humphrey_Bogart_1940.jpg/480px-Humphrey_Bogart_1940.jpg",imageCredit:"Warner Bros., 1940 (public domain)",wikiTitle:"Humphrey_Bogart",keyWorks:[{title:"Casablanca",year:1942,notes:`"Here's looking at you, kid" — perhaps the most quoted film in history`},{title:"The Maltese Falcon",year:1941,notes:"The archetypal hard-boiled detective film"},{title:"The Big Sleep",year:1946,notes:"With Lauren Bacall — whose chemistry defined screen romance"},{title:"The African Queen",year:1951,notes:"His only Academy Award — Best Actor"},{title:"In a Lonely Place",year:1950,notes:"His most complex and psychologically dark performance"}],quote:"The only point in making money is so you can tell some big shot where to go.",tags:["actor","film-noir","golden-age","american","hard-boiled"]},{id:"ingmar-bergman",name:"Ingmar Bergman",lifespan:"1918 – 2007",birthYear:1918,deathYear:2007,category:"FILM_TV",subcategory:"Director & Writer",nationality:"Swedish",era:"European Art Cinema",eraColor:"#374151",bio:`Ingmar Bergman is the supreme artist of existential cinema — the filmmaker who most unflinchingly interrogated faith, death, the silence of God, and the war between men and women. Born in Uppsala, Sweden, to a Lutheran pastor father whose stern, repressive household cast a shadow over his entire creative life, he became first a theater director before entering film. The Seventh Seal (1957) — a medieval knight playing chess with Death — gave the world its most enduring image of philosophical cinema. Wild Strawberries (1957), released the same year, is a gentler, more personal reckoning with a life's regrets. His "trilogy of faith" — Through a Glass Darkly, Winter Light, The Silence — made between 1961 and 1963, explores the anguished absence of God with an austerity that borders on cruelty. Persona (1966) is among the most formally radical films ever made. He ended his career with the magnificently life-affirming Fanny and Alexander (1982).`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Ingmar_Bergman_1957.jpg/480px-Ingmar_Bergman_1957.jpg",imageCredit:"Anon., 1957 (public domain)",wikiTitle:"Ingmar_Bergman",keyWorks:[{title:"The Seventh Seal",year:1957,notes:"The chess-with-Death image is cinema's most iconic"},{title:"Wild Strawberries",year:1957,notes:"A professor revisits his life on the eve of receiving an honorary degree"},{title:"Persona",year:1966,notes:"One of cinema's most formally experimental films"},{title:"Fanny and Alexander",year:1982,notes:"His final theatrical feature — luminous and life-affirming"},{title:"Scenes from a Marriage",year:1973,notes:"Originally a TV miniseries — devastatingly honest about marriage"}],tags:["art-cinema","swedish","existential","director","faith"]},{id:"federico-fellini",name:"Federico Fellini",lifespan:"1920 – 1993",birthYear:1920,deathYear:1993,category:"FILM_TV",subcategory:"Director & Writer",nationality:"Italian",era:"Italian Art Cinema",eraColor:"#F59E0B",bio:`Federico Fellini transformed cinema into an art of dream, memory, and fantasy — a deeply personal theater of the unconscious that made his name synonymous with a kind of visionary, self-referential filmmaking. Born in Rimini on the Adriatic coast, he worked as a caricaturist and gag writer before partnering with director Roberto Rossellini. La Strada (1954), his most tender film, won the first Academy Award for Best Foreign Language Film. But his most audacious work came later: La Dolce Vita (1960) — a panorama of decadent Roman celebrity life — gave the world the word "paparazzi." 8½ (1963) is cinema's most celebrated meditation on creative crisis, depicting a film director overwhelmed by memory and fantasy. Fellini invented the personal, self-referential film as a genre, and without him there is no Woody Allen, no Almodóvar, no much of modern cinema.`,imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Federico_Fellini.jpg/480px-Federico_Fellini.jpg",imageCredit:"Anon., c.1965 (public domain)",wikiTitle:"Federico_Fellini",keyWorks:[{title:"La Strada",year:1954,notes:"Won the first Academy Award for Best Foreign Language Film"},{title:"La Dolce Vita",year:1960,notes:'Coined the word "paparazzi"; a portrait of Roman decadence'},{title:"8½",year:1963,notes:"Cinema's greatest meditation on artistic creation and memory"},{title:"Amarcord",year:1973,notes:"Nostalgic reverie of his Rimini childhood; won the Foreign Language Oscar"}],quote:"A different language is a different vision of life.",tags:["italian","surrealism","director","art-cinema","rome"]},{id:"audrey-hepburn",name:"Audrey Hepburn",lifespan:"1929 – 1993",birthYear:1929,deathYear:1993,category:"FILM_TV",subcategory:"Actress",nationality:"British",era:"Golden Age of Hollywood",eraColor:"#6366F1",bio:"Audrey Hepburn — one of the few entertainers to achieve EGOT status (Emmy, Grammy, Oscar, Tony) — represented something new in Hollywood: an elegance that was at once ethereal and accessible, a luminous presence that transformed every film she appeared in. Born in Brussels to an English father and Dutch baroness mother, she spent years of her childhood in Arnhem during the Nazi occupation of the Netherlands — years of deprivation that marked her for life and deepened her later humanitarian work. Roman Holiday (1953), her Hollywood debut, won her the Academy Award at 24. Breakfast at Tiffany's (1961) made her the emblem of a generation. Sabrina, Funny Face, Charade, Wait Until Dark, My Fair Lady — each showcased her unique combination of vulnerability and inner strength. In her final decades she devoted herself entirely to UNICEF work, traveling to impoverished communities across Africa and Latin America.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Audrey_Hepburn_in_Sabrina_1954_trailer.jpg/480px-Audrey_Hepburn_in_Sabrina_1954_trailer.jpg",imageCredit:"Paramount Pictures, 1954 (public domain)",wikiTitle:"Audrey_Hepburn",keyWorks:[{title:"Roman Holiday",year:1953,notes:"Her debut — won the Academy Award at 24"},{title:"Breakfast at Tiffany's",year:1961,notes:'"Moon River" became her signature; she is Holly Golightly'},{title:"Sabrina",year:1954,notes:"Billy Wilder's romantic comedy — her Givenchy wardrobe defined fashion"},{title:"Wait Until Dark",year:1967,notes:"Psychological thriller — her most frightening film"}],quote:`Nothing is impossible. The word itself says "I'm possible!"`,tags:["actress","golden-age","humanitarian","fashion","egot"]}];function m(t,e=0){const a=t==="MUSIC"?s:l,i=1440*60*1e3,r=Math.floor(Date.now()/i)+e;return a[(r%a.length+a.length)%a.length]}function c(t){let e=5381;for(let a=0;a<t.length;a++)e=(e<<5)+e^t.charCodeAt(a),e=e>>>0;return e}function u(t,e,a=0){const i=e==="MUSIC"?s:l,r=1440*60*1e3,h=Math.floor(Date.now()/r)+a;let o=0;if(t)o=c(t)%i.length;else{const n=localStorage.getItem("plajah_anon_history_seed");if(n)o=parseInt(n,10)||0;else{o=Math.floor(Math.random()*i.length);try{localStorage.setItem("plajah_anon_history_seed",String(o))}catch{}}}const d=((h+o)%i.length+i.length)%i.length;return i[d]}export{l as F,s as M,m as a,u as g};
